#!/usr/bin/env bash
# Acadia-HAL — per-repo validation gate (stack: cmake).
# Generated by tools/validate/generate.sh. Edit freely afterwards.
#
#   quick   seconds. Repo shape + proto sanity, no build.
#   full    minutes. Configure + build + ctest + lint.
#
# HAL owns the canonical .proto contracts and generated gRPC code. Client and
# Server link it via add_subdirectory and must NEVER regenerate protos — the
# no-regeneration rule is a C++ ODR constraint. HAL itself may regenerate.
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# --- quick -----------------------------------------------------------------

assert "CMakeLists present" 'test -f CMakeLists.txt'
assert "proto registry present" 'test -f protos/registry/modules.yaml'
assert "proto sources parse (syntax declarations)" \
  'for f in $(find protos -name "*.proto" 2>/dev/null); do
     grep -q "^syntax" "$f" || { echo "$f has no syntax declaration"; exit 1; }
   done'

# C++ ODR rule: Client/Server must never regenerate. HAL is the owner.
assert "generated sources are not gitignored (must stay tracked)" \
  '! git check-ignore -q gen 2>/dev/null || { echo "gen/ is gitignored; it must stay tracked"; exit 1; }'

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

check "configure" "cmake ninja" 'make configure'
check "build" "cmake ninja g++" 'make build'
check "tests (ctest)" "cmake" 'make test'
check "lint (cppcheck + clang-format)" "cppcheck clang-format" 'make lint'

report "$TIER"
